    "answer_tr": "نجاستلر ایکی قسمدر :<br>1 - نجاست غلیظه آغیر قالین پیسلکلر انسان وجودندن چیقمش اولان و آبدستی و یا غسلی ایجاب ایدن بوتون شیلر نجاست غلیظه در مثلا انسانك أوك و أرقادن چیقان پیسلكي، أتى بينمه ين حيوانلرك بولی دیشقیسی و صالیاسی طاووق قاز و أوردكك ديشقيسي، قان إيرين منى مذى ودى آغیز طولوسی ،قوصمق شراب و دیگر حرام ایچکیلر.<br>حکمی بو نجاستلر، کیپسیلرده بدنده و یا نماز قیلیناجاق پرده بولونورسه قاتی اولانلرك ۳،۲ اوچ ویرکول ایکی) غرامدن فضله سی، صيوى اولانلرك ايسه آل آیاسی قادار و یا دها فضله سی نمازه ما نعدر.<br> - نجاست خفیفه خفیف) بيسلكلر : آتك بولى، أتى بينن اهلي و ياباني حيوانلرك پيسلكي، أتى بينمه ين قوشارك ديشقيسيدر.<br>حکمی بو نجاستلر إصابت ايتديكي عضوك ويا ألبسه نك دورتده برندن فضله ایسه نمازه مانعدر.",
    "question_id": "Ada berapa jenis najis dan apa saja itu?",
    "answer_id": "Najis ada dua jenis:<br>1. Najis Ghalizah (Najis Berat/Kental): Semua yang keluar dari tubuh manusia dan mewajibkan wudu atau mandi adalah najis ghalizah. Contohnya: kotoran yang keluar dari depan dan belakang manusia, kotoran dan liur hewan yang dagingnya tidak dimakan, kotoran ayam, angsa, dan bebek, darah, nanah, mani, madzi, wadi, muntah yang memenuhi mulut, khamr (minuman keras), dan minuman haram lainnya.<br>Hukumnya: Jika najis ini mengenai tubuh, pakaian, atau tempat shalat, maka jika najis padat, lebih dari 3,2 gram (sekitar dua dirham), dan jika cair, seluas telapak tangan atau lebih, maka shalat tidak sah.<br>2. Najis Khafifah (Najis Ringan): Kencing kuda, kotoran hewan peliharaan dan liar yang dagingnya dimakan, dan kotoran burung yang dagingnya tidak dimakan.<br>• Hukumnya: Jika najis ini mengenai seperempat atau lebih dari anggota tubuh atau pakaian yang terkena, maka shalat tidak sah.",
