    "answer_id": "Makruh dalam shalat:<br>1. Melihat ke kanan dan ke kiri saat shalat.<br>2. Membunyikan jari tanpa uzur.<br>3. Membersihkan kerikil di tempat sujud.<br>4. Duduk bersila tanpa uzur.<br>5. Shalat dengan kepala terbuka.<br>6. Shalat berdampingan dengan wanita tanpa penghalang.<br>7. Mendahului imam dalam rukuk.<br>8. Bangkit dari rukuk mendahului imam.<br>9. Sujud mendahului imam.<br>10. Bangkit dari sujud mendahului imam.",
