    "answer_tr": "جماعت ایله نماز فيلمانك حكمي: سنت مؤکده در .<br>امامته اك لايق اولانلر: ۱- سنتى اك أبي بيلندر اكر) اوراده بولونانلر سنتي بيلمك باقیمندن مساوی ایسه لر)<br>٢- قرائتي أك كوزل اولان قرائت با قیمندن ده مساوی ایسه لر)<br>اك وراع و تقوى صاحبي اولانی. (ینه مساوی ایسه لر)<br>- اك يا شليلرى امام اولور.<br>• کوله، بدوی، فاسق، ایکی کوزی کور و ولد زنا اولان كيمسه نك نماز قيلديرماسى مكروهدر. فقط امام اولسه لر نماز جائز اولور.",
