    "question_id": "Apa saja waktu-waktu karahah (terlarang/dibenci untuk shalat)?",
    "answer_id": "• Waktu-waktu karahah ada tiga: terbitnya matahari (thulu'), saat matahari di tengah-tengah langit (istawa'), dan terbenamnya matahari (ghurub).<br>• Shalat tidak boleh dilakukan pada tiga waktu ini: saat matahari terbit, saat matahari di puncak ketinggian (zawâl), dan saat matahari terbenam.<br>• Shalat jenazah yang telah disiapkan sebelum waktu-waktu ini tidak boleh dilakukan pada waktu-waktu ini.<br>• Sujud tilawah dari ayat yang telah dibaca sebelumnya juga tidak boleh dilakukan pada waktu-waktu ini.<br>• Namun, shalat fardu Ashar pada hari itu dapat dilakukan saat matahari hampir terbenam.<br>• Makruh mengerjakan shalat sunah setelah shalat Subuh hingga matahari terbit, dan setelah shalat Ashar hingga matahari terbenam.",
