    "question_tr": "خسته نمازینی نصل قیلار؟",
    "answer_tr": "۱- خسته عذری سببیله آیا قده نماز فیلمایه قادر اولمادیغی ،زمان نمازینی رکوع و سجده ایله او تورارق قيلار.<br>۲- اگر رکوع و سجده به کوجی بیتمزسه سجده سنی رکوعندن آشاغی اولمق اوزره ايماء ايده رك قيلار.<br>خسته او تورمایه مقتدر دکلسه صیرت اوستی یاتار و آیا قلرینی قبله یه طوغری اوز اتارق رکوع و سجده یی ایماء ایله یا پارق نمازینی قیلار<br>٤- ايماء ايتميه ده کوجی بیتمز سه؛ نمازینی تأخير ايدر كوز قاش و قلب ایله ايماء اولماز.<br>بر کیمسه ایماء ایله نماز ،قیلارکن رکوع و سجده اوزرینه قادر اولسه - ضعیف اوزره قوتلي بي بناء ايتمك اولا جغندن - نمازی یکیدن قیلار.",
    "question_id": "Bagaimana cara shalat orang sakit?",
    "answer_id": "1. Jika orang sakit tidak mampu shalat sambil berdiri karena uzur, maka ia shalat sambil duduk dengan rukuk dan sujud.<br>2. Jika ia tidak mampu rukuk dan sujud (sempurna), maka ia shalat dengan isyarat (mengangguk), di mana sujudnya lebih rendah daripada rukuknya.<br>3. Jika orang sakit tidak mampu duduk, maka ia berbaring telentang, meluruskan kakinya ke arah kiblat, dan shalat dengan isyarat untuk rukuk dan sujud.<br>4. Jika ia juga tidak mampu melakukan isyarat; maka ia menunda shalatnya. Isyarat dengan mata, alis, atau hati tidak sah.<br>5. Jika seseorang shalat dengan isyarat, kemudian mampu melakukan rukuk dan sujud (sempurna), maka ia harus mengulang shalatnya, karena ini berarti menguatkan yang lemah.",
