    "question_tr": "بايغينلق ويا ايماء ايله ده اولسه فيلاما یا جق دره جه ده کی خسته لرك قيلا ماد قلری نماز لرك حكمى نه در؟",
    "answer_tr": "• باييلمقدن طولایی بش وقت و یا دها از نمازی قضایه قالان بر کیشی أیبلشدیکی زمان او نمازلرینی قضاء ایتمه ليدر. اگر بشدن فضله نمازی قضایه قالیرسه هیچ بریسی قضاء ایدیلمز .<br>• ايماء ایله نماز فیلمایه ده کوجي ييتمه ين كيمسه نك خسته لغى صو كرادن خفيفلرسه اكر بو كيمسه نك عجزي بر كون بر کیجه دن فضله اولورسه نمازلرینی قضاء ایتمه سی کر کمز. فقط بوندن آز اولورسه قضاء لازم اولور.",
    "question_id": "Bagaimana hukum shalat yang terlewat oleh orang sakit parah karena pingsan atau tidak mampu shalat bahkan dengan isyarat?",
    "answer_id": "• Jika seseorang pingsan dan terlewat shalat lima waktu atau kurang, ia wajib mengqada shalat-shalat tersebut setelah sembuh.<br>• Jika shalat yang terlewat lebih dari lima waktu, maka tidak ada qada baginya.<br>• Jika seseorang tidak mampu shalat bahkan dengan isyarat, lalu sakitnya membaik, jika ketidakmampuannya itu lebih dari satu hari satu malam, ia tidak perlu mengqada shalat-shalatnya.<br>• Namun, jika kurang dari itu, maka qada wajib baginya.",
