    "question_tr": "وطن قاچ قسمدر ؟",
    "answer_tr": "وطن اوچ قسمدر : ۱- وطن اصلی - وطن اقامت ۳- وطن سکنی<br>وطن اصلى كيشينك طوغديغي ويا أولنديكى يردر يا شامایه نیت ایدوپ آیریلمق ایسته مه دیکی برده وطن اصلی در وطن اصلی آنحق وطن اصلی ایله بوزولور بر كيشينك بردن فضله خانمی اولوپ هر برهری آیری آیری شهر لرده اولسه لر هیچ برنده سفری اولماز.<br>وطن اقامت مسافرك أك از اون بش كون قالمایه نیت ایتدیکی و وطن اصلی سنه (۹۰) طوقسان کیلومتره مسافه ده بولونان یردر. بوراده نمازلر قيصالتيلماز. وطن إقامت؛ وطن اصلی ایله و باشقه بر وطن اقامت ایله بوزولور. وطن سكنى ايله بوزولماز.<br>وطن سكنى مسافرك اون بش کوندن از قالمایه نیت ایتدیکی و اصل وطننه (۹۰) طوقسان كيلومتره و یا دها فضله مسافه ده بولونان پردر بوراده دورت رکعتلی فرضلر ایکی رکعت قيلينير.<br>• مسافر بر کیمسه سفرده قضایه قالان دورت رکعتلی فرضلری سفرده و یا مملکتنه دوندیکنده ایکی رکعت اولارق قضاء ايدر.<br>• مقیم ایکن قضایه قالان نمازلری ایسه دورت رکعت اولارق قضاء ايدر.",
    "question_id": "Ada berapa jenis Watan (tempat tinggal)?",
    "answer_id": "Watan ada tiga jenis:<br>1. Watan Asli: Tempat kelahiran seseorang, atau tempat di mana ia menikah, atau tempat di mana ia berniat untuk tinggal dan tidak ingin meninggalkannya. Watan asli hanya batal dengan watan asli lainnya. Jika seseorang memiliki lebih dari satu istri yang tinggal di kota-kota yang berbeda, ia tidak menjadi musafir di kota-kota tersebut.<br>2. Watan Iqamah: Tempat di mana seorang musafir berniat tinggal minimal 15 hari, dan jaraknya 90 kilometer atau lebih dari watan aslinya. Di sini, shalat tidak dipendekkan. Watan iqamah batal dengan watan asli dan watan iqamah lainnya. Ia tidak batal dengan watan sukna.<br>3. Watan Sukna: Tempat di mana seorang musafir berniat tinggal kurang dari 15 hari, dan jaraknya 90 kilometer atau lebih dari watan aslinya. Di sini, shalat fardu empat rakaat dipendekkan menjadi dua rakaat.<br>• Seorang musafir yang memiliki shalat fardu empat rakaat yang terlewat saat bepergian, mengqadanya menjadi dua rakaat, baik saat masih dalam perjalanan maupun setelah kembali ke negerinya.<br>• Adapun shalat yang terlewat saat ia mukim, ia mengqadanya menjadi empat rakaat.",
