    "answer_tr": "• حکمی: کندیسنه جمعه قیلمق فرض اولانلره بایرام نمازی واجبدر.<br>• وقتی کونشك يوكسلمه سيله بايرام نمازينك وقتي كيرر زواله قدر دوام ايدر.<br>• بایرام نمازی شویله قیلینیر امام جماعته ایکی رکعت نماز قیلدیرر برنجی رکعتده افتتاح تکبیرینی كتيرر، \"سبحانك\" اوقور، اوندن صوكرا أللرينى قالدير ارق اوج تكبير داها كتيرر صوكرا فاتحه شریفه و بر ضم سوره او قود قدن صو کره بر تکبیر كتيره رك ركوعه كيدر. ايكنجی رکعته قرائت ایله باشلار، \"فاتحه شریفه و بر ضم سوره\" اوقود قدن صوکره اوچ تکبیر آلیر و دور د نجی تكبيرى كتيره رك ركوعه کیدر ایکی بایرام نمازى تكبير لرنده ده اللرينى قالديرر و يانينه بيراقير.<br>• تكبير لرك حكمى واجبدر نمازدن صوکره خطبه اوقور.",
    "question_id": "Apa hukum shalat Id? Kapan waktunya? Apa hukum takbir-takbirnya?",
    "answer_id": "• Hukumnya: Shalat Id wajib bagi mereka yang diwajibkan shalat Jumat.<br>• Waktunya: Waktu shalat Id dimulai ketika matahari terbit dan meninggi, dan berlanjut hingga zawal (tergelincirnya matahari).<br>• Cara mengerjakan shalat Id: Imam mengimami jamaah dua rakaat. Pada rakaat pertama, ia mengucapkan takbiratul ihram, membaca \"Subhanakallahumma\", kemudian mengangkat tangan dan mengucapkan tiga takbir lagi. Setelah itu, ia membaca Al-Fatihah dan surah tambahan, lalu mengucapkan satu takbir dan rukuk. Pada rakaat kedua, ia memulai dengan bacaan, setelah membaca Al-Fatihah dan surah tambahan, ia mengucapkan tiga takbir, lalu mengucapkan takbir keempat dan rukuk. Dalam takbir-takbir kedua shalat Id, ia mengangkat tangan dan menurunkannya ke samping.<br>• Hukum takbir-takbirnya: Wajib. Setelah shalat, ia membaca khotbah.",
