    "answer_tr": "جنازه نمازينك حکمی: فرض کفایه در .<br>جنازه نمازينك قيلينيشي: دورت تكبير و بر قيام ايله أدا ايديلير بو نمازده سجده و رکوع يوقدر. امام أولونك كوكسى حذاسنده دورور جماعت ده آرقاسنده صف طوتار. جماعته أولونك اركك و يا قادين اولديغنى دويورور او کا کوره نیت ايديلير.<br>یعنی \"الله ايچون نمازه میت ایچون دعایه از کیشی و یا خاتون کیشی نیتنه او يدوم حاضر اولان امامه\" ديه قلبا نيت ایدوب امامك ارقاسندن تكبير آلينير.<br>ايلك تكبيرى اليركن أللر قولاق حذاسنه قدر قالديريلوب كوبك آلتنده باغلانير. سبحانك \" و جل ثناؤك ايله اوقونور بوندن صوكرا أللر قالدير يلمادن ایکنجی بر تکبیر آلینیر بو تکبیرلری امام آشکار جماعت ایسه كيزلي آلير. اللهم صل و اللهم بارك . \" اوقونور بوندن صوکرا او چنجی تکبیر آلینیر و جنازه دعاسی اوقونور.<br>جنازه دعاسنی بیلمه ينلر بوراده اللهم انا نستعينك\" يي یعنی قنوت دعاسنی و یا دعا نيتي ايله فاتحه شریفه یی او قورلر داها صوكرا دوردنجی تكبير آلينير، أللر يان طرفه بيراقيلوب سلام ويريلير.",
    "question_id": "Apa hukum shalat jenazah? Bagaimana cara mengerjakannya?",
    "answer_id": "Hukum shalat jenazah: Fardu kifayah.<br>• Cara mengerjakannya: Dilakukan dengan empat takbir dan satu berdiri (qiyam). Tidak ada sujud dan rukuk dalam shalat ini.<br>• Imam berdiri sejajar dada jenazah. Jamaah berbaris di belakangnya.<br>• Imam memberitahukan kepada jamaah apakah jenazah itu laki-laki atau perempuan. Niat disesuaikan dengannya.<br>• Yaitu, seseorang berniat dalam hati: \"Allah ایچون نمازه میت ایچون دعایه از کیشی و یا خاتون كيشي نيتنه او يدوم حاضر اولان امامه (Saya niat shalat karena Allah, berdoa untuk jenazah ini (laki-laki atau perempuan), mengikuti imam yang hadir ini), lalu bertakbir di belakang imam.<br>• Saat takbir pertama, tangan diangkat sejajar telinga dan dilipat di bawah pusar. Kemudian dibaca \"Subhanakallahumma\" dan \"Jalla Tsana'uka\".<br>• Setelah itu, takbir kedua diambil tanpa mengangkat tangan. Takbir-takbir ini diucapkan oleh imam dengan suara keras, sedangkan makmum dengan suara pelan. Kemudian dibaca \"Allahumma shalli\" dan \"Allahumma barik\".<br>• Setelah itu, takbir ketiga diambil dan dibaca doa jenazah.<br>• Bagi yang tidak tahu doa jenazah, boleh membaca \"Allahumma inna nasta'inuka\" (yaitu doa qunut) atau Surah Al-Fatihah dengan niat doa.<br>• Setelah itu, takbir keempat diambil, tangan diturunkan ke samping, dan diucapkan salam.",
