    "question_tr": "کفن نه در؟ قاچ قسمدر ؟ أركك و قادينلر ايچون سنت اولان کفن نه لر در؟",
    "answer_tr": "كفن وفات ايدن مسلمانك صاريلوب قبره قونولدیغی بزدر.<br>کفن اوچ قسمدر ۱ کفن سنت - كفن كفايه - كفن ضروره<br>کفن سنت: أرككلر ایچون اوچ پارچه اولوپ قميص إزار لفافه در قادینلر ایچون ایسه بش پارچه در؛ قمیص، إزار، لفافه، باش (خمار) و كوكوس أورتوسى (خرقة) در .<br>كفن كفايه أرككلر ایچون إزار و لفافه قادینلر ایچون ایسه إزار لفافه و باش آورتوسی در.<br>کفن ضروره ایسه یالکز بر قائدر بو قادار ده بولو ناماز سه جنازه بر بزه صاريلوب كومولور.",
    "question_id": "Apa itu kafan? Ada berapa jenisnya? Apa saja kafan sunah untuk laki-laki dan perempuan?",
    "answer_id": "• Kafan: Kain yang digunakan untuk membungkus jenazah muslim yang meninggal dan ditempatkan di kuburan.<br>• Kafan ada tiga jenis: 1- Kafan Sunah, 2- Kafan Kifayah, 3- Kafan Dharurah.<br>• Kafan Sunah: Untuk laki-laki ada tiga potong: kemeja, izar (kain sarung), dan lifafah (kain pembungkus). Untuk perempuan ada lima potong: kemeja, izar, lifafah, khimar (penutup kepala), dan khirqah (penutup dada).<br>• Kafan Kifayah: Untuk laki-laki adalah izar dan lifafah. Untuk perempuan adalah izar, lifafah, dan penutup kepala.<br>• Kafan Dharurah: Hanya satu potong kain. Jika tidak ada kain sebanyak itu, jenazah dibungkus dengan kain apa adanya lalu dikubur.",
