    "answer_tr": "مقتدى إمامه اويان كيشى یه دینور اوچ قسمدر:<br>۱ - مدرك : نمازك باشندن صو کنه قدر فاصله سر اولارق إمامه اويان و بتون رکعتلری امام ایله برابر قیلان کیمسه در.<br>مسبوق برنجی رکعت قیلند قدن صوكره إمامه اويان كيمسه در که صوك او تورو شده دخى إمامه اويسه مسبوق صاييلير. مسبوق قضاء ايده جكى ركعتلرده تك باشینه نماز قیلان کی در.<br>لاحق نمازه إمامله برابر با شلادیغی حالده بر عذر سببیله نمازك تمامنی و یا بر قسمنى إمامله قیلامیان کیمسه در.",
    "question_id": "Siapa itu Muqtadi (makmum)? Ada berapa jenisnya?",
    "answer_id": "Muqtadi adalah orang yang mengikuti imam. Ada tiga jenis:<br>1. Mudrik: Orang yang mengikuti imam dari awal hingga akhir shalat tanpa terputus, dan mengerjakan semua rakaat bersama imam.<br>2. Masbuq: Orang yang mengikuti imam setelah rakaat pertama dikerjakan. Jika ia mengikuti imam bahkan di duduk terakhir, ia tetap dianggap masbuq. Masbuq mengerjakan rakaat yang terlewat seolah-olah ia shalat sendirian.<br>3. Lahiq: Orang yang memulai shalat bersama imam, tetapi karena suatu uzur tidak bisa menyelesaikan seluruh atau sebagian shalat bersama imam.",
