    "question_id": "Oruç (Puasa) ada berapa jenis?",
    "answer_id": "Puasa ada enam jenis:<br>1. Fardu: Puasa Ramadan (ada'), qada, dan kafarat.<br>2. Wajib: Qada puasa sunah yang dibatalkan dan puasa nazar.<br>3. Sunah: Puasa tanggal 9 dan 10 (Asyura) bulan Muharram.<br>4. Mandub (Dianjurkan): Puasa tiga hari setiap bulan.<br>5. Nafilah (Sunah Tambahan): Puasa-puasa selain yang disebutkan ini, selama tidak makruh.<br>6. Makruh: Puasa hanya pada hari Asyura saja. Puasa pada hari pertama Idul Fitri dan hari pertama, kedua, ketiga, keempat Idul Adha adalah makruh tahriman (makruh yang mendekati haram), karena berarti menolak jamuan Allah Ta'ala.",
