    "question_tr": "نكاحك تعريفی ندر؟ ركنی ندر؟ شرطلری ندر؟ حكمی ندر؟ وصفی ندر؟ شاهدسز نكاح اولورمی؟",
    "answer_tr": "لغتده: ضم وجمع معناسينه در.<br>شرعا: ايجاب وقبول ايله منعقد اولان قصدا ملك متعه يى إفاده ايدن بر عقددر.<br>ركنى: إيجاب و قبولدر.<br>شرطلری: ۱- معلوم زوج و زوجه نك بر مجلسده موجوديتى، ۲- ايجاب وقبولى دويان شاهدلرك حاضر اولماسى، ۳- نكاحك دائمى اولماسى، ۴- شرعى بر مانعدن خالى اولمق.<br>حكمى: زوج وزوجه نك بر بريندن استفاده سنك حلال اولماسى، مهر، نفقه و كييم زوج اوزرينه فرض اولماسى، اوكجه اولنك مالنه ديكرينك وارث اولماسيدر.<br>وصفى: توقان حالنده زنايه دوشمه احتمالى قطعى ايسه فرض، قطعى دكلسه واجب، اعتدال حالنده سنت، ظلم احتمالى وارسه مكروه، ظلم كسين ايسه حرامدر.<br>شاهدسز نكاح اولماز. ايكى اركك ويا بر اركك ايكى قادينك شاهدلكى ايله عقد ياپيلير.",
    "question_id": "Apa definisi nikah? Apa rukun, syarat, hukum, dan sifatnya? Apakah sah nikah tanpa saksi?",
