    "answer_tr": "محرمات، نكاحلانيلماسى دينا حرام اولان قادينلردر. ايكى قسمدر: مؤبدا و موقتا.<br>مؤبدا اوچ قسمدر:<br>۱- نسبا حرام اولانلر: آننهلر، قيزلر، قيز قاردشلر، تيزەلر، خالالر، ايركك قاردشلرك قيزلری، قيز قاردشلرك قيزلری.<br>۲- صهريت/اوليلك سببيله حرام اولانلر: قاين والدهلر، اوى آننهلر، اوى قيزلر، كلينلر.<br>۳- رضاع/اممك سببيله حرام اولانلر: سوت آننهلر، سوت قيزلر، سوت نينهلر، سوت قيز قاردشلر، سوت تيزەلر، سوت خالالر، سوت قيز و اوغلان قاردشلرك قيزلرى.<br>موقتا حرام اولانلر: بر نكاحده جمعى جائز اولميان قادينلر، دورد قادينله اولى اولمق، اوچ طلاقله بوشانيلان قادين (حله مستثنى)، باشقه لرينك نكاحنده كى قادين، غير كتابى اهل شرك.",
    "question_id": "Siapa saja Muharramat dan ada berapa jenisnya?",
    "answer_id": "Muharramat adalah wanita-wanita yang haram dinikahi. Ada dua jenis: yang haram selamanya (mu'abbadan) dan yang haram sementara (muwaqqatan).<br>Mu'abbadan ada tiga bagian:<br>1. Haram karena nasab (keturunan): ibu, anak perempuan, saudara perempuan, bibi (saudara ayah), bibi (saudara ibu), anak perempuan saudara laki-laki, anak perempuan saudara perempuan.<br>2. Haram karena mushaharah (pernikahan): mertua perempuan, ibu tiri, anak tiri (jika sudah digauli ibunya), menantu perempuan.<br>3. Haram karena radha' (persusuan): ibu susu, saudara perempuan sepersusuan, nenek susu, bibi sepersusuan, anak perempuan saudara sepersusuan.<br>Muwaqqatan: wanita yang tidak boleh dikumpulkan dalam satu pernikahan, wanita yang menjadi istri orang lain, wanita musyrik bukan ahli kitab, wanita yang ditalak tiga (sebelum halalan).",
