    "answer_tr": "محرم: نكاحى حرام اولان ياقين قادينلردر.<br>نامحرم: نكاحى حرام اولميان/حلال اولان قادينلردر (اقربا اولسونلر اولماسونلر).<br>نامحرملك صينيرى: خالا، تيزه، دايى و عمجهلرك قيزلرندن اعتبارا باشلار. يعنى بونلر ايله اوليلك جائزدر. عمجه و دايينك خانمى اولان ينكهلر ايله، اركك قاردشلرينك خانمى اولان ينكهلر ده اولويتله نامحرمدر. بو نامحرملر ايله \"خلوت اولمق\" حرامدر.",
    "question_id": "Apa itu Mahram dan Na-Mahram?",
    "answer_id": "Mahram: wanita dekat yang haram dinikahi.<br>Na-Mahram: wanita yang tidak haram (halal) dinikahi, baik kerabat maupun bukan kerabat.<br>Batas mahram dimulai dari sepupu (anak bibi dan paman). Artinya, menikahi mereka adalah halal. Istri paman (bibi ipar) dan istri saudara laki-laki (kakak/adik ipar) termasuk na-mahram secara prioritas. Oleh karena itu, berkhalwat (berduaan) dengan na-mahram adalah haram.",
