    "question_id": "Apakah sah menikahi Ahli Kitab?",
    "answer_id": "Menikahi wanita Ahli Kitab adalah sah. Menikahi wanita penyembah berhala dan penyembah api tidak diperbolehkan. Jika mereka beriman kepada seorang nabi dan mengakui sebuah kitab, maka boleh dinikahi. Namun, jika mereka menyembah bintang dan tidak mengakui kitab, tidak boleh menikahi mereka.<br>Adapun wanita Muslimah, mereka tidak diizinkan untuk menikah dengan laki-laki non-Muslim meskipun Ahli Kitab.",
