    "question_tr": "ولیسينك اذن اولمادن نكاح اولورمی؟ ولیسى باله اولان باكره يى نكاحه زورلايابيلیر مى؟",
    "answer_tr": "امام اعظم حضرتلرينه كوره حر، عاقل، بالغ ايسه ولینك اذن اولمادن كندى رضاسى ايله جائز اولور. امامينه كوره اولماز.<br>ولیسینك، بالغه اولان بر باكره يى نكاحه زورلاماسى جائز دكلدر.<br>ولیسى، باكره قيزدن اذن ايستهدیكى زمان، صوصارسه ويا كولرسه ويا آغلارسه بو حاللر اذن ويرمك ديمكدر. دول قاديندن اذن ايستهدیكى زمان، سوزله رضاسنى بليرتمسى لازمدر.",
    "question_id": "Apakah sah nikah tanpa izin wali? Bolehkah wali memaksa perawan yang sudah baligh untuk menikah?",
    "answer_id": "Menurut Imam A'zam: jika wanita merdeka, berakal, dan baligh, maka nikahnya sah dengan keridhaan sendiri tanpa izin wali. Menurut kedua Imam (Abu Yusuf dan Muhammad): tidak sah.<br>Tidak diperbolehkan bagi wali untuk memaksa perawan yang sudah baligh untuk menikah.<br>Ketika wali meminta izin kepada gadis perawan, jika ia diam, tertawa, atau menangis, maka itu dianggap sebagai izin. Jika ia tidak memberi izin, wali tidak boleh menikahkannya. Untuk janda, ia harus mengungkapkan keridhaan secara lisan.",
