    "answer_tr": "نكاح حكم اولارق اوچه آيريلير: نكاح منعقد (صحيح)، نكاح باطل، نكاح فاسد.<br>نكاح منعقد: صحت شرطلرينى تماما جامع اولان نكاحدر.<br>نكاح باطل: اوزرينه اصلا نكاح حكملرى ترتب ايتمهين نكاحدر. مثلا: غير مميز و مجنون ايله نكاح، ايجاب و قبول اولمادن ياپيلان نكاح، متعه نكاحى.<br>نكاح فاسد: اول امرده منعقد اولان آما صوكرادن بر مانع ايله بوزولان نكاحدر. مثلا شاهدسز نكاح، بر محرم ايله بيله رك نكاح.",
    "question_id": "Ada berapa jenis nikah? Apa itu nikah bathil dan nikah fasid?",
