    "answer_tr": "لغة: ممه اممك، سوت اممك معناسينه در.<br>شرعا: خصوصى وقتده آدمينك كوكسوندن چوجوغك سوت اممهسيدر.<br>رضاع مدتى: امام اعظم حضرتلرينه كوره ۳۰ آى (ايكى بوچوق سنه)، امامينه كوره ايسه ايكى سنهدر. رضاعك آزى و چوغى، امزيرمه مدتنده ميدانه كليرسه مساويدر و حراملق تعلق ايدر.<br>حكمى: امهنك امزيره نه نفسى حرام، امزيره نك امهنه نسلى حرامدر.",
    "question_id": "Apa definisi Radha' (persusuan)? Berapa lama masa persusuan?",
    "answer_id": "Secara bahasa: menyusu, menghisap susu.<br>Secara syariat: Seorang bayi menghisap susu dari payudara seorang wanita pada waktu tertentu yang telah ditentukan.<br>Masa radha': Menurut Imam A'zam, 30 bulan (dua setengah tahun); menurut kedua Imam, dua tahun. Sedikit atau banyaknya persusuan dalam masa itu sama, dan menghasilkan keharaman.<br>Hukumnya: Yang menyusui menjadi haram bagi dirinya (si bayi), dan keturunan yang menyusui menjadi haram bagi si bayi.",
