    "answer_tr": "لغة: بوشامق، حسى ويا معنوى بر قيددن قورتولمقدر.<br>شرعا: نكاح سببيله شرعا ثابت اولان نكاح باغينى قالديرمقدر. حر قادينك طلاقى اوچدر، جاريه نك ايسه ايكيدر.<br>طلاق، شكلى اعتباريله ۳ قسمدر:<br>۱- احسن طلاق: ارككك خانمنى بر طهر دونمنده بوشاييب اوكا هيچ ياقلاشمادن عدتنى بيتيرمهسيدر.<br>۲- سنت طلاق: ارككك خانمنى هر طهر دونمنده برر طلاق ايله بوشاماسى و بو زمان ايچونده خانمنه ياقلاشمامش اولماسيدر.<br>۳- بدعت طلاق: ارككك خانمنى بر كلمه ايله اوچ طلاق بردن بوشاماسي ويا بر طهر دونمنده اوچ آيرى طلاق ايله بوشامش اولماسيدر. قوجه كناهكار اولور.",
    "question_id": "Apa itu talak? Ada berapa jenis talak?",
