    "answer_tr": "طلاق لفظلر جهتندن ايكى قسمدر:<br>۱- طلاق بالصريح: (ط-ل-ق) حرفلرندن مشتاق، صريح/آچيق لفظلرله ويريلن طلاقدر. (انت طالق، انت مطلقة، طلقتك) كبى. بوكيشينك نيته باقيلماز، بر طلاق رجعى واقع اولور.<br>۲- طلاق بالكناية: اصلا طلاق ايچون وضع اولونمایب هم طلاقه هم ده باشقه معنالرده قوللانيلان لفظلردر. بو لفظلرله طلاقك واقع اولماسى نيته ياخود طلاق مذاكره سى كبى بر شيئه محتاجدر.",
    "question_id": "Apa itu talak Sharih (terang) dan talak Kinayah (sindiran)?",
    "answer_id": "Talak dari segi lafaz ada dua jenis:<br>1. Talak Sharih: Talak dengan lafaz terang yang berasal dari huruf (ط-ل-ق), seperti 'Anti thaalik', 'Anti muthallaqa', 'Thalaqtuki'. Niat tidak dilihat; otomatis jatuh satu talak raj'i.<br>2. Talak Kinayah: Lafaz yang pada dasarnya tidak khusus untuk talak tetapi bisa berarti talak atau hal lain. Jatuhnya talak tergantung pada niat atau konteks pembicaraan tentang talak.",
