    "answer_tr": "طلاق رجعى: زوجك طلاقدن صوكره، قادينك عدتى مدتنجه دونوپ نكاحه دوام ايتمه حقى اولان طلاقدر. عدت ايچه ريسنده زوجه نك رضاسينه باقيلمقسزك يكى بر نكاح عقدنه احتياج اولمادن زوجك رجعتيله نكاح دوام ايدر.<br>طلاق باين: زوجه نك عدتى دوام ايدركن زوجك رجعت حقى اولمايان، رجعت زوجه نك رضاسينه باغلى اولان و تجديد نكاح و مهر ايجاب ايدن طلاقدر.<br>بينونت صغرى: بر ويا ايكى طلاق باين ايله ميدانه كلن طلاقدر. تجديد نكاح و مهرله يكيدن اوله نيله بيلير.<br>بينونت كبرى: بر دفعه ده ويا آيرى آيرى اوچه تمامله نن طلاقدر. حله اولمقسزك تكرار اوله نيله مز.",
    "question_id": "Apa itu talak raj'i dan talak ba'in? Apa hukumnya?",
    "answer_id": "Talak raj'i: Talak di mana suami masih berhak rujuk selama masa idah istri tanpa akad baru. Jika suami rujuk dalam masa idah, pernikahan berlanjut tanpa perlu akad baru dan tanpa perlu persetujuan istri.<br>Talak ba'in: Talak di mana suami tidak memiliki hak rujuk, dan kembalinya tergantung kerelaan istri dengan akad dan mahar baru.<br>Bainunah Shughra: Satu atau dua talak ba'in. Boleh menikah lagi dengan akad dan mahar baru.<br>Bainunah Kubra: Talak tiga (bisa sekaligus atau bertahap). Tidak boleh menikah lagi sebelum istri menikah dengan laki-laki lain dan bercerai dari pernikahan tersebut (halalan).",
