    "question_tr": "ايلاء، خلع، ظهار و لعان ندر؟",
    "answer_tr": "ايلاء: قوجهنك نكاحلى قاريسينه دورت آي ويا دها فضله ياقلاشمامق اوزره ياپديغى يميندر. قوجه ايلا مدتنده ياقلاشمازسه بر طلاق باين واقع اولور، ياقلاشيرسه كفارت ويرمه سى لازمدر.<br>خلع: قادينك اوده مهيى قبول ايتديكى بر مال مقابلنده اوليلك عقدينه صوك ويريلمه سيدر. قادين بر طلاق باين ايله بوشانمش اولور.<br>ظهار: ارككك زوجه سينى ويا زوجه سينك بر جزئنى نسبا ويا رضاعا محرمى اولان بيريسينك باقيلماسى حرام اولان بر عضوينه تشبيه ايتمه سيدر. ظهار ياپان اركك كفارت ويرينجه يه قدر خانمينه ياقلاشاماز.<br>لعان: زوج ايله زوجه نك حاكم حضورنده شرعى اصولنه اويغون اولارق دورت دفعه شهادتده بولوندقدن صوكره ارككك لعنت، قادينك غضب اوقويارق آيريلمالريدر.",
    "question_id": "Apa itu Ila', Khul', Zhihar, dan Li'an?",
    "answer_id": "Ila': Sumpah suami untuk tidak mendekati istrinya selama empat bulan atau lebih. Jika suami tidak mendekati istri selama masa ila', maka jatuh satu talak ba'in. Jika mendekati, ia wajib membayar kafarat sumpah.<br>Khul': Pemutusan ikatan pernikahan dengan imbalan harta yang disepakati istri. Dengan khul', istri dicerai dengan satu talak ba'in dan wajib membayar tebusan.<br>Zhihar: Seorang suami menyerupakan istrinya dengan bagian tubuh mahramnya yang tidak boleh dilihat. Suami tidak boleh mendekati istrinya sebelum membayar kafarat zhihar.<br>Li'an: Suami dan istri saling bersumpah di hadapan hakim setelah empat kali kesaksian; suami mendapat laknat dan istri mendapat murka Allah, kemudian mereka berpisah.",
