    "question_tr": "عدت ندر؟ مدتلرى نه قدردر؟",
    "answer_tr": "عدت لغتا: صايمق معناسينه در. شرعا: نكاح ملكينك ازالهسى سببيله قادينك باشقاسى ايله اولهنه بيلمهسى ايچون بكله مهسى لازم كلن مدتدر.<br>عدت مدتلرى:<br>۱- بوشانمش قادين حر اولوپ حيض كورويورسه اوچ حيض مدتى، جاريه ايسه ايكى حيضدر.<br>۲- بوشانمش قادين حيض كورميورسه اوچ آى، جاريه ايسه بر بوچوق آى.<br>۳- بوشانمش قادين حامله ايسه حملينى وضع ايدنجه يه قدر.<br>۴- قوجهسى اولن قادين، دورت آى اون كون، جاريه ايكى آى بش كون بكلر.",
    "question_id": "Apa itu Idah? Berapa lama masa idah?",
    "answer_id": "Idah secara bahasa: menghitung. Secara syariat: masa tunggu yang wajib dijalani wanita setelah berakhirnya ikatan pernikahan sebelum boleh menikah lagi.<br>Masa-masa idah:<br>1. Wanita yang dicerai dan masih mengalami haid: tiga kali haid (untuk wanita merdeka) atau dua kali haid (untuk budak perempuan).<br>2. Wanita yang dicerai dan tidak mengalami haid (karena usia tua atau muda): tiga bulan (merdeka) atau satu setengah bulan (budak).<br>3. Wanita yang dicerai dalam keadaan hamil: sampai melahirkan.<br>4. Wanita yang ditinggal mati suaminya: empat bulan sepuluh hari (merdeka) atau dua bulan lima hari (budak).",
