    "question_tr": "نفقه ندر؟ بر كيمسه كيملرك نفقهسى ايله مكلفدر؟",
    "answer_tr": "نفقه: انسانك ياشايابيلمهسى ايچون محتاج اولديغى ييهجك، كييهجك و اَوكى شيلردر.<br>اسلامده عائله رئيسى اولارق قادينك و چوجوقلرك كچيمينى صاغلامق كوره وى ارككه ويريلمشدر. آيريجه آننه، باباء، قاردشلر و ديكر خصيملر باكيمه محتاج دورومه دوشونجه كچيمى صاغلامه يوكوملولكى اونلرى ده قاپسار.<br>اولى قادينك نفقه سى: خانمى اونه تسليم ايتديكى زمان بتون ييهجك، كييهجك و مسكن مصرفلرى قوجهيه عائددر.",
    "question_id": "Apa itu Nafaqah? Siapa saja yang wajib diberi nafaqah?",
    "answer_id": "Nafaqah: segala sesuatu yang dibutuhkan seseorang untuk dapat hidup, berupa makanan, pakaian, dan tempat tinggal.<br>Dalam Islam, kewajiban menafkahi istri dan anak-anak diberikan kepada laki-laki (suami) sebagai kepala keluarga. Selain itu, jika orang tua, saudara, dan kerabat lainnya membutuhkan, kewajiban nafaqah juga mencakup mereka.<br>Nafaqah istri: Ketika istri menyerahkan dirinya kepada suami di rumahnya, maka seluruh biaya makanan, pakaian, dan tempat tinggal menjadi tanggungan suami, sesuai dengan taraf hidup keduanya.",
