    "answer_tr": "حضانه لغتا: چوجوغى تربيه ايتمك معناسينه در. شرعا: نكاحك بوزولماسندن صوكرا، چوجوغى صلاحيتلى اولان كيمسهنك بليرلى بر ياشه كلنجهيه قدر ياننده حمايه و تربيه ايتمه سيدر.<br>اشلر آيريلديغنده آننه چوجوغك تربيهسينه دها اويغوندر. آننه اولماديغى تقديرده آننهنك آننهسى، باباننك آننهسندن اوله در.<br>اركك چوجوق تك باشينه ييوب ايچوب، البسهسينى كييوب و طهارتينى ياپنجهيه قدر آننهسى ياننده دها اولادر. قيز چوجوق حيض كورونجهيه قدر آننهسى ياننده اولماسى اولادر.",
    "question_id": "Apa itu Hadhanah (hak asuh anak)?",
    "answer_id": "Hadhanah secara bahasa: merawat dan mendidik anak. Secara syariat: Memelihara dan mendidik anak oleh orang yang berwenang hingga anak mencapai usia tertentu (laki-laki hingga 7 tahun, perempuan hingga dewasa/haid) setelah pernikahan bubar.<br>Ketika orang tua berpisah, ibu lebih layak merawat anak karena penuh kasih sayang. Jika tidak ada ibu, maka nenek dari pihak ibu lebih utama dari nenek pihak ayah.<br>Untuk anak laki-laki: Lebih baik bersama ibu atau nenek hingga ia bisa makan, minum, berpakaian, dan bersuci sendiri.<br>Untuk anak perempuan: Lebih baik bersama ibu atau nenek hingga ia haid.",
