    "question_tr": "جنايت ندر؟ قتل قاچ قسمدر؟ قتل عمد و شبه عمد ندر و حكملرى ندر؟",
    "answer_tr": "جنايت؛ بر انسان اولدورمك ويا بر عضوينى كسمك، قيرمق معناسينه در.<br>قتل بش قسمدر: قتل عمد، قتل شبه عمد، قتل خطا، خطا مجراسينه اجرا اولونان قتل، قتل بسبب.<br>قتل عمد (قصدا اولدورمك): سلاح و سلاح وظيفهسى كورن پارچالاييجى بر شيله اولدورمك ديمكدر. حكمى: گناهكارلق و قصاصدر. مقتولك وليلرى عفو ايدرسه قصاص دوشر، كفارت يوقدر.<br>قتل شبه عمد: امام اعظم حضرتلرينه كوره سلاح و سلاحك يرينه قائم اولمايان بر شيله ووروپ اولدورمكدر. حكمى: گناهكار اولمق، كفارت و عاقله اوزرينه ديت مغلظه لازم كلمهسيدر. بوندا قصاص يوقدر.",
    "question_id": "Apa itu Jinayat? Ada berapa jenis pembunuhan? Apa itu pembunuhan sengaja dan semi-sengaja?",
    "answer_id": "Jinayat berarti membunuh seseorang atau memotong/melukai anggota tubuhnya.<br>Pembunuhan ada lima jenis: pembunuhan sengaja, semi-sengaja, keliru, yang dijalankan seperti keliru, dan karena sebab.<br>Pembunuhan Sengaja (Qatl 'Amad): membunuh dengan senjata atau benda tajam yang dapat melukai. Hukumnya: dosa dan qisas. Jika wali korban memaafkan, qisas gugur. Tidak ada kafarat.<br>Pembunuhan Semi-Sengaja (Qatl Syibhu 'Amad): Menurut Imam A'zam, memukul dengan benda yang bukan senjata hingga tewas. Hukumnya: berdosa, wajib kafarat dan diyat mughallazah (yang diperberat) atas 'aqilah (keluarga pelaku). Tidak ada qisas.",
