    "question_tr": "قتل خطا و خطا مجراسينه اجرا اولونان قتل ندر؟ سبب ايله قتل ندر؟",
    "answer_tr": "قتل خطا ياكليشلقله اولدورمك ايكى شكلده اولور:<br>۱- قصدده خطا: بر انسان آو ظن ايدهرك آتيپ اولدوردقدن صوكره انسان اولديغينى كورمك كبى.<br>۲- فعلده خطا: اوقو هدفينه آتديغى حالده بر انسانه اصابت ايتمهسى كبى.<br>حكمى: كفارت و عاقله اوزرينه ديتك لازم اولماسيدر. بوراده گناه يوقدر.<br>خطا مجراسينه اجرا اولونان قتل: اويويان بر كيمسهنك باشقه بريسينك اوزرينه دوشوپ اولدورمهسى كبى. حكمى: كفارت و عاقله اوزرينه ديتك لازم اولماسيدر.<br>سبب ايله قتل: ملكنده دكلده باشقه بر يرده قويو قازان ويا طاش ديكن بر كيمسهنك حركتى كبى. حكمى: ياقينلرينه ديتك ترتب ايتمهسيدر، كفارت يوقدر.",
    "question_id": "Apa itu pembunuhan keliru dan pembunuhan karena sebab? Apa hukumnya?",
    "answer_id": "Pembunuhan Keliru (Qatl Khatha') terjadi dalam dua bentuk:<br>1. Keliru dalam niat: Menyangka sasaran adalah hewan buruan, lalu memanahnya dan ternyata manusia.<br>2. Keliru dalam perbuatan: Memanah ke target namun mengenai manusia.<br>Hukumnya: Kafarat dan diyat wajib atas 'aqilah. Tidak ada dosa, karena tidak disengaja.<br>Pembunuhan yang Dijalankan Seperti Keliru: Seseorang yang sedang tidur jatuh menimpa orang lain hingga tewas. Hukumnya sama.<br>Pembunuhan Karena Sebab: Menggali sumur atau meletakkan batu di tempat bukan miliknya, lalu seseorang terperosok hingga tewas. Hukumnya: diyat wajib atas keluarganya, tidak ada kafarat.",
