    "question_tr": "قتل كفارتى ندر؟ ديت ندر و نه قدردر؟",
    "answer_tr": "قتل كفارتى (خطا و شبه عمدده): مومن بر كوله يى آزاد ايتمكدر. او اولمادیغى تقديرده آرقه آرقهيه ايكى آى اوروچ طوتمقدر، التمش فقيره ييديرمك يوقدر.<br>ديت: اولدورمه ياده يارالامه كبى ايشله نن بر جنايت سببيله مغدوره ياده وارثلرينه جان بدلى اولارق ويريلن مالدر.<br>ديت مغلظه: قتل شبه عمد ايله اولدورمه ده ايجاب ايدر كه يوز دوه ويرمكدر.<br>نورمال ديت: قتل خطا ايله اولدورمه ده ايجاب ايدر كه امام اعظم حضرتلرينه كوره يوز دوه، التوندن ايسه بيك دينار، گوموشدن اون بيك درهمدر.",
    "question_id": "Apa itu kafarat pembunuhan? Apa itu Diyat dan berapa kadarnya?",
    "answer_id": "Kafarat pembunuhan (untuk keliru dan semi-sengaja): Memerdekakan seorang budak mukmin. Jika tidak mampu, berpuasa dua bulan berturut-turut. Tidak ada kewajiban memberi makan 60 orang miskin.<br>Diyat: Harta yang dibayarkan kepada korban atau ahli warisnya sebagai pengganti jiwa akibat tindak kejahatan seperti pembunuhan atau pelukaan.<br>Diyat Mughallazah (Diperberat): Wajib dalam pembunuhan semi-sengaja, yaitu 100 ekor unta.<br>Diyat Normal: Wajib dalam pembunuhan keliru. Menurut Imam A'zam: 100 ekor unta, atau 1.000 dinar emas, atau 10.000 dirham perak.",
