    "question_tr": "ارش ندر؟ شجه ندر و قاچ قسمدر؟",
    "answer_tr": "ارش لغة: بدل، تضمينات. شرعا: قتلك غيرى اعضالردهكى جنايتلرده مغدوره اودهنن ديتدر.<br>شجه، باشده و يوزده ميدانه كلن يارالر ديمك اولوپ اون قسمدر:<br>۱- حارصه {يالگز ده رى ييرتيلمش}<br>۲- دامعه {گوز ياشى قدر قان چيقمش}<br>۳- داميه {گوز ياشى قدر قان چيقيپ سيلان}<br>۴- باضعه {ده رى ايله برابر برازده ات كسيلمش}<br>۵- متلاحمه {ده رى ايله برابر آپيجه ات كسيلمش}<br>۶- سمحاق {ات ايله كميك آراسنده كى اينجه زار كبى ده رى كورنمه باشلامش}<br>۷- موضحه {كميك ميدانه چيقمش - قصدا ايسه قصاص، خطا ايسه ييرميده بر}<br>۸- هاشمه {كميك قيريلمش - ييرميده ايكى}<br>۹- منقله {كميك قيريليپ ييريندن اوينامش - ييرميده اوچ}<br>۱۰- آمه {دماغه اولاشان يارا - ديت كاملهنك اوجده برى}",
    "question_id": "Apa itu Arsy? Apa itu Syajjah dan ada berapa jenisnya?",
    "answer_id": "Arsy secara bahasa: ganti rugi, tanggungan. Secara syariat: diyat yang dibayarkan kepada korban dalam tindak kejahatan terhadap anggota tubuh selain pembunuhan.<br>Syajjah adalah luka-luka yang terjadi di kepala dan wajah, ada sepuluh jenis:<br>1. Harishah: Hanya kulit yang sobek.<br>2. Dami'ah: Darah keluar sebesar air mata.<br>3. Damiyah: Darah mengalir.<br>4. Badhi'ah: Daging terpotong.<br>5. Mutalahimah: Daging terpotong dalam.<br>6. Simhaq: Lapisan tipis antara daging dan tulang mulai terlihat.<br>7. Mudhihah: Tulang terlihat - jika sengaja: qisas; jika keliru: 1/20 diyat.<br>8. Hasyimah: Tulang retak - 2/20 diyat.<br>9. Munqilah: Tulang patah dan bergeser - 3/20 diyat.<br>10. Ammah: Luka hingga mencapai otak - 1/3 diyat penuh.",
