    "question_tr": "حد ندر؟ زنانك حكمى ندر و نه ايله ثابت اولور؟ حد زنا ندر؟",
    "answer_tr": "حدود، حدك جمعيدر. شرعا: اللهك حقى اولارق، امام اوزرينه يرينه كتيرمهسى واجب اولان، تقدير اولونمش جزالردر.<br>زنانك حكمى: حرامدر. زنا دليل و اقرار ايله ثابت اولور. دليل ايله: دورت اركك بر اركك و قادين اوزرينه زنا ايتدكلرينه شاهدلك ياپديغى زمان ثابت اولور. اقرار ايله: بالغ و عقللى بر كيمسهنك دورت مجلسده دورت دفعه زنا ايتديكنى اقرار ايتمهسيدر.<br>حد زنا: زنا ياپانلر محصن و محصنه ايسه رجم ايله اولدورولور. باكار ايسه يوز صوپه وورولور.<br>محصن و محصنه: مسلمان، حر، عقللى و بالغ اولوپ باشندن صحيح بر نكاح كچمش اولان اركك و قادين.",
    "question_id": "Apa itu Had? Apa hukum zina dan bagaimana pembuktiannya? Apa itu had zina?",
    "answer_id": "Had (jamak: Hudud) secara syariat: Hukuman-hukuman tertentu yang ditetapkan Allah dan wajib dilaksanakan oleh penguasa.<br>Hukum zina: Haram. Zina dibuktikan dengan kesaksian atau pengakuan. Dengan kesaksian: empat orang laki-laki bersaksi melihat keduanya berzina. Dengan pengakuan: seseorang yang baligh dan berakal mengakui perbuatan zina dalam empat majelis yang berbeda.<br>Had Zina: Jika pezina Muhshan (pernah menikah), dihukum rajam hingga mati. Jika belum pernah menikah (bikr), dicambuk 100 kali.<br>Muhshan dan Muhshanah: Laki-laki dan perempuan yang Muslim, merdeka, berakal, baligh, dan pernah menjalani pernikahan yang sah.",
