    "question_tr": "حد شرب ندر؟ جزاسى ندر؟",
    "answer_tr": "حد شرب ايكى قسمدر:<br>۱- شراب ايجمك: بوندا بر داملا بيله ايجسه كافيدر. سرخوش اولما شرطى آرانماز.<br>۲- شرابك خارجنده حرام اولان مسكراتى ايجمك: بوندا سرخوش اولما شرطى آرانر.<br>حد شربك ثابت اولماسى: شرابى ايچركن طوتوقلانان بر كيمسه ده قوقوسى موجود اولورسه، ايچديكينه دائر شاهدلر شهادت ايدرسه ويا ايچديكينى اقرار ايدرسه ثابت اولور.<br>جزاسى: حر ايسه ۸۰ صوپه، كوله ايسه ۴۰ صوپه.<br>سرخوش اولمانك علامت: امامينه كوره قونوشوركن كلمه لرى قاريشديران، امام اعظمه كوره قادين ايله ارككى - ارض ايله سماءيى تفريق ايده مهين كيمسه.",
    "question_id": "Apa itu Had Syurb (minum khamar)? Apa hukumannya?",
    "answer_id": "Had Syurb ada dua jenis:<br>1. Meminum khamar: Satu teguk pun sudah cukup (untuk pembuktian). Tidak dipersyaratkan mabuk.<br>2. Meminum minuman keras selain khamar: Dipersyaratkan sampai mabuk.<br>Pembuktian had minum: Jika seseorang tertangkap sedang minum dan tercium baunya, atau ada saksi yang bersaksi, atau ia sendiri mengakuinya.<br>Hukumannya: 80 cambukan untuk orang merdeka, 40 cambukan untuk budak.<br>Tanda mabuk: Menurut kedua Imam, ketika kata-katanya sudah kacau. Menurut Imam A'zam, ketika tidak bisa membedakan antara laki-laki dan perempuan, atau antara langit dan bumi.",
