    "question_tr": "قذف ندر؟ حد قذف ندر؟ تعزير ندر؟",
    "answer_tr": "قذف لغتا: آتمق معناسينه در. شرعا: عفتلى و ناموسلى بريسينه زنا افتراسنده بولونمق ديمكدر.<br>اصطلاحلر: قاذف: زنا افتراسى آتان. مقذوف: زنا افتراسينه اوغرايان.<br>حد قذف: محصن و محصنه اولان اركك و قادينه آچيقجه زنا افتراسنده بولونديغى و افترايه اوغرايان حدى طلب ايتديكى زمان حاكم حد تطبيق ايدر.<br>جزاسى: حر ايسه ۸۰ صوپه، كوله ايسه ۴۰ صوبه.<br>تعزير: حققنده معين بر جزا اولمايان صوجلردن طولايى تطبيق ايديلن جزادر. مقدارى: اك چوغى ۳۹ صوپه، اك آزى اوچ صوپه.",
    "question_id": "Apa itu Qadzaf (tuduhan zina)? Apa itu had Qadzaf? Apa itu Ta'zir?",
    "answer_id": "Qadzaf secara bahasa: melempar. Secara syariat: menuduh orang yang baik dan terhormat dengan tuduhan berzina.<br>Hukum had Qadzaf: Jika seseorang menuduh laki-laki atau perempuan yang muhshan dengan tuduhan zina secara terang-terangan, dan pihak yang dituduh meminta pelaksanaan had, maka hakim menegakkan had.<br>Hukumannya: 80 cambukan untuk orang merdeka, 40 cambukan untuk budak.<br>Ihshan (untuk pihak yang dituduh): Orang yang dituduh harus merdeka, berakal, baligh, Muslim, dan terpelihara dari perbuatan zina.<br>Ta'zir: Hukuman yang diterapkan untuk pelanggaran yang tidak ada had tertentu. Kadarnya: paling banyak 39 cambukan, paling sedikit tiga cambukan.",
