    "question_tr": "سرقت ندر؟ حد سرقت ندر؟",
    "answer_tr": "سرقت لغتا: صاحبنك اذن اولمادن بر شيئ كزليجه آلمقدر.<br>سرقت شرعا: مكلفك، كيزليجه اون درهم دكريندهكى بر شيئى آلماسيدر.<br>حد سرقتك ثابت اولماسى: ايكى شاهدك شهادتى ويا كنديسينك اقرارى ايله ثابت اولر.<br>حد سرقت: حدك تطبيقى، خيرسزك صاغ الى بيلكدن كسيلير و قايناق ياغى ايله قاپاتيلير. ايكنجى دفعه خيرسزلق ياپارسه صول آياغى كسيلير. اوچوجنى كز تكرار ياپارسه امام اون توبه ايدنجه يه قدر حبسه آتار.",
    "question_id": "Apa itu Sariqah (pencurian)? Apa itu had Sariqah?",
    "answer_id": "Sariqah secara bahasa: Mengambil sesuatu milik orang lain secara sembunyi-sembunyi tanpa izin pemiliknya.<br>Sariqah secara syariat: Seorang mukallaf mengambil secara sembunyi-sembunyi harta senilai 10 dirham atau lebih.<br>Pembuktian had pencurian: Dengan kesaksian dua orang saksi atau pengakuan pelaku sendiri.<br>Had pencurian: Tangan kanan pencuri dipotong dari pergelangan dan diberi kauterisasi dengan minyak mendidih. Jika mencuri kedua kalinya, kaki kirinya dipotong. Jika mencuri ketiga kalinya, imam memenjarakannya hingga ia bertobat.",
