    "originalNumber": 163,
    "question_tr": "حرام اولان ايچكيلر نهلردر؟",
    "answer_tr": "حرام اولان ايچكيلر دورتدر:<br>۱- شراب: پيشيريلمه دن قاينایوپ كسكينله شن و كوپوكون آتان اوزوم صوييدر.<br>۲- اوچده ايكيسندن آزى گيدينجه يه قدر قايناتيلان اوزوم صوييدر.<br>۳- قورى خورما نقيعى (شيراسى).<br>۴- قورى اوزوم نقيعى (بو ايكيسى شددتلنديكى زمان حرام اولور).",
    "question_id": "Apa saja minuman yang diharamkan?",
    "answer_id": "Minuman yang diharamkan ada empat:<br>1. Khamar: Air perasan anggur yang menggelembung, mengeras, dan berbusa tanpa dimasak.<br>2. Air perasan anggur yang dimasak hingga kurang dari 2/3-nya menguap.<br>3. Nabidz kurma kering (perasan yang mengeras).<br>4. Nabidz anggur kering (ketika kedua minuman ini menjadi kuat/memabukkan, maka haram).",
