    "question_tr": "صيد و ذبايح ندر؟ بوغازلامهده كسيلن طامارلر نهلردر؟",
    "answer_tr": "صيد: آو ديمكدر. اكيتيملى كلب، پارس و شاهين كبى قوشلر ايله آولانمق جائزدر.<br>ذبايح: كسيلمهسى جائز اولان حيوانلر ديمكدر.<br>بوغازلامهده كسيلن طامارلر دورتدر:<br>۱- حلقوم (نفس بوروسى)<br>۲- مرى (يهمك و ايچمك بوروسى)<br>۳ و ۴- بوغازك ايكى طرفنده كى قان بورولرى (ودج).<br>بتون بو طامارلر كسيلديكنده يينمهسى حلال اولور. امام اعظم حضرتلرينه كوره چوغون (يعنى اوچنى) كسرسه ينه يينير. اكر قربان كسن بسمه له يى قصدا ترك ايدرسه كسديكى حيوان مرداردر، اتى ينمز.",
    "question_id": "Apa itu Shayd (berburu) dan Dzabayih (sembelihan)? Apa saja urat yang wajib dipotong saat menyembelih?",
    "answer_id": "Shayd: Berburu. Berburu menggunakan anjing terlatih, cheetah, dan burung seperti elang adalah halal.<br>Dzabayih: Hewan yang halal disembelih.<br>Urat-urat yang dipotong saat menyembelih ada empat:<br>1. Hulqum (tenggorokan/saluran napas).<br>2. Mari' (kerongkongan/saluran makan dan minum).<br>3 dan 4. Dua pembuluh darah di kedua sisi leher (wadj).<br>Jika semua urat ini dipotong, dagingnya halal dimakan. Menurut Imam A'zam: memotong mayoritas (yaitu tiga) sudah cukup. Jika penyembelih sengaja meninggalkan basmalah, hewannya bangkai dan dagingnya tidak boleh dimakan.",
