    "question_tr": "اضحيه و حكمى ندر؟ قربان وقتى ندر؟",
    "answer_tr": "اضحيه: خصوصى وقتده حضرت اللهه ياقينلق نيتيله خصوصى حيوان كسمكدر. مسلمان، حر، بالغ، هر زنكين و مقيم اولان كيمسه يه، كنديسى و كوچوك چوجوقلرى ايچون قربان بايرامنده قربان كسمك واجبدر. دوه، صيغير (يدى كيشى كسه بيلير) و طاواردن اولور.<br>قربان وقتى: بايرام گوننك فجرى ايله باشلار، آنجاق امام بايرام نمازينى قيلديرمادقجه شهرليلره قربان كسيلمهسى جائز دكلدر. قربان اوچ كوندر (بايرامك برنجى، ايكنجى، اوچنجى كونى). برنجى كون افضلدر.",
    "question_id": "Apa itu Udhhiyah (kurban) dan apa hukumnya? Kapan waktu berkurban?",
    "answer_id": "Udhhiyah: Menyembelih hewan tertentu pada waktu tertentu (hari raya Idul Adha) dengan niat mendekatkan diri kepada Allah. Wajib bagi setiap Muslim yang merdeka, baligh, mampu, dan mukim untuk menyembelih kurban untuk dirinya dan anak-anak kecilnya. Kurban bisa dari unta, sapi (boleh patungan 7 orang), atau kambing/domba.<br>Waktu kurban: Dimulai dari fajar hari raya, tetapi bagi penduduk kota tidak boleh menyembelih sebelum imam selesai mengimami shalat Id. Kurban boleh dilakukan selama tiga hari (hari pertama, kedua, ketiga Idul Adha). Hari pertama lebih utama.",
