    "question_tr": "يمين ندر؟ قاچ قسمدر؟ يمين كفارتى ندر؟",
    "answer_tr": "يمين: يمين ايدهنك ياپمهيه ويا ياپمهميه كنديسيله عزم ايتديكى قوتلى بر عقددن عبارتدر. اوچ قسمدر:<br>۱- يمين غموس: كچمش بر ايش ايچون بيله بيله يالانله يمين ايتمكدر. كناهكار اولور، استغفارك باشقه كفارت يوقدر.<br>۲- يمين منعقده: كله جك بر امرى ياپيپ ويا ياپمايا جاغينه دائر ياپديغى يميندر. بو يمينى يرينه كتيرمزسه كفارت ويرمهسى لازم كلير.<br>۳- يمين لغو: كچمش زماندا اولان بر شيئه طوغرى اولديغينى ظن ايدهرك ايتديكى يمينله، حقيقت بونك خلافنهدر. حضرت اللهك بو يمين سببيله صاحبنى مواخذه ايتمهيهجكنى اميد ايديريز.<br>يمين كفارتى: ۱- كوله آزاد ايتمك، ۲- اون مسكينى كيدير مك ويا طويورمق، ۳- پش پشه اوچ كون اوروچ طوتمق.",
    "question_id": "Apa itu Yamin (sumpah)? Ada berapa jenisnya? Apa itu kafarat sumpah?",
    "answer_id": "Yamin (sumpah): Ikatan kuat yang dilakukan seseorang untuk melakukan atau tidak melakukan sesuatu. Ada tiga jenis:<br>1. Yamin Ghumus: Bersumpah dusta tentang suatu yang telah lalu dengan sengaja. Berdosa, tidak ada kafarat selain istighfar.<br>2. Yamin Mun'aqidah: Sumpah untuk melakukan atau tidak melakukan sesuatu di masa mendatang. Jika dilanggar, wajib membayar kafarat.<br>3. Yamin Laghwi: Bersumpah tentang sesuatu di masa lalu yang diyakini benar, padahal ternyata salah. Kita berharap Allah tidak meminta pertanggungjawabannya.<br>Kafarat sumpah: 1) Memerdekakan budak; 2) Memberi makan atau pakaian kepada sepuluh orang miskin; 3) Berpuasa tiga hari berturut-turut.",
