    "question_tr": "شهادت ندر؟ شهادت قاچ مرتبه اوزرينه در؟",
    "answer_tr": "شهادت: كسين اولارق، ظن و تحمين اولمقسزك بر كيمسه نك بر باشقه سينده اولان حقنى خبر ويرمكدر.<br>شهادتلر دورت مرتبه اوزرينه در:<br>۱- زنا حققنده شاهدلك: آنجاق دورت اركك معتبردر. قادينلرك شاهدلكى مقبول دكلدر.<br>۲- حد و قصاص ديشنده كى مسئلهلرده كى شاهدلك: ايكى كيشينك شاهدلكى قبول اولونور. قادينلرك قبول اولونماز.<br>۳- بونلردن باشقه حقلرده: ايكى اركك ويا بر اركك ايكى قادينك شاهدلكى قبول اولونور.<br>۴- طوغوم، باكره لك و ارككلرك مطلع اولماسى ممكن اولمايان يرلرده: تك بر خانمك شاهدلكى قبول اولونور.",
    "question_id": "Apa itu Syahadah (kesaksian)? Ada berapa tingkatan kesaksian?",
    "answer_id": "Syahadah: Memberitahukan hak seseorang pada orang lain secara meyakinkan, tanpa keraguan.<br>Kesaksian terdiri dari empat tingkatan:<br>1. Kesaksian tentang zina: Hanya empat laki-laki yang diterima. Kesaksian perempuan tidak diterima.<br>2. Kesaksian di luar had dan qisas: Dua orang saksi diterima. Kesaksian perempuan tidak diterima.<br>3. Dalam hak-hak lainnya: Kesaksian dua laki-laki atau satu laki-laki dan dua perempuan diterima (baik hak harta maupun non-harta seperti nikah, cerai, dsb).<br>4. Dalam masalah yang tidak dapat diketahui laki-laki (seperti persalinan, keperawanan, dan aib tersembunyi): Kesaksian satu perempuan saja diterima.",
