    "question_tr": "قسامه ندر؟ مرتد كيمدر؟ جهاد ندر؟",
    "answer_tr": "قسامه: قاتلى مجهول اولان و اوزرنده قتل اثرى بولونان بر مقتولك بولونديغى محل آهاليسندن اللى كيشيه اون اولدورمه دكلرينه دائر يمين ايتديريلمهسيدر. يمين ايتدكدن صوكره او محله ساكينلرينه ديتى يوكله نير.<br>مرتد: مسلمان ايكن ديندن چيقان، كافر اولان كيمسه در. بر مسلمان اسلامدن دونديكى زمان كنديسينه اسلامك حقيقتى آكلاتيلير، شبههسى وارسه ازاله ايديلير و اوچ كون حبسه آتيلير. مسلمان اولورسه بيراقيلير، كفرنده اصرار ايدرسه اولدورولور. قادين مرتد اولورسه اولدورولمز، مسلمان اولونجه يه قدر حبس اولونور.<br>جهاد: مسلمان، حر، بلوغ چاغينه ارمش ارككلره فرض كفايه در.",
    "question_id": "Apa itu Qasamah? Siapa itu Murtad? Apa itu Jihad?",
    "answer_id": "Qasamah: Lima puluh orang penduduk kampung tempat ditemukannya mayat dengan bekas pembunuhan yang tidak diketahui pelakunya, bersumpah bahwa mereka tidak membunuh dan tidak mengetahui siapa yang membunuh. Setelah bersumpah, diyat dibebankan kepada penduduk kampung tersebut.<br>Murtad: Orang Muslim yang keluar dari agama Islam dan menjadi kafir. Ketika seorang Muslim murtad, ia diberitahu tentang kebenaran Islam, dihilangkan keraguan-keraguannya, dan dipenjara tiga hari. Jika ia kembali Islam, ia dibebaskan; jika ia bersikeras dalam kekafirannya, ia dihukum mati. Wanita yang murtad tidak dihukum mati, tetapi dipenjara hingga kembali masuk Islam.<br>Jihad: Fardu kifayah bagi laki-laki Muslim yang merdeka dan baligh.",
