    "question_tr": "وصيت و حكمى ندر؟ حظر و اباحه ندر؟",
    "answer_tr": "وصيت: بر كيمسهنك اولومندن صوكرهيه مضاف قيلارق مالينى باشقهسينه تبرع و تمليك ايتمه سيدر. وصيت ياپمق واجب دكل مستحبدر. تركه نك اوچده برندن فضله سيله وصيت ياپمق جائز دكلدر.<br>حظر: شرعا استعمالندن منع اولونان شيدر.<br>اباحه: حلال قيلمق، مباح قيلمق، سربست بيراقمق، حظرك ضديدر.<br>مباح: ثواب ويا عقابه مستحق اولمقسزك مكللفلرك ايشله مهسينه و ترك ايتمهسينه اجازت ويريلن شيدر.<br>نوط: ييپك كييمك ارككلره حرام، قادينلره حلالدر. آلتون و گوموش قاپلردن ييمك ايچمك جائز دكلدر.",
    "question_id": "Apa itu Wasiat dan apa hukumnya? Apa itu Hazr dan Ibahah?",
    "answer_id": "Wasiat: Seseorang menyerahkan hartanya secara sukarela kepada orang lain yang berlaku setelah kematiannya. Berwasiat tidak wajib, melainkan mustahab (dianjurkan). Tidak boleh berwasiat melebihi sepertiga harta warisan.<br>Hazr: Sesuatu yang dilarang digunakan secara syar'i.<br>Ibahah: Menghalalkan, membolehkan; lawan dari hazr.<br>Mubah: Sesuatu yang pelakunya tidak berhak mendapat pahala atau hukuman, dan diizinkan untuk dilakukan atau ditinggalkan.<br>Catatan penting: Memakai sutera haram bagi laki-laki, halal bagi perempuan. Makan dan minum dari wadah emas atau perak tidak diperbolehkan.",
